e-stat-go-jp-stat-search.original_month_method:
@staticmethod
def _survey_month_date(text: str | None) -> str | None:
        if not text:
            return None
        match = re.search(r"(\d{4})\s*年\s*(\d{1,2})\s*月", text)
        if match:
            return f"{match.group(1)}-{int(match.group(2)):02d}-01"
        return None

