@staticmethod
def _stat_infid_from_url(url: str) -> str | None:
        parsed = urllib.parse.urlparse(url)
        params = urllib.parse.parse_qs(parsed.query)
        value = params.get("stat_infid") or params.get("statInfId")
        return value[0] if value else None
